System.out.println(String.class.getClassLoader());
// null - String jest czescia rdzenia JDK (java.lang.*), ladowana przez Bootstrap Class
// Loader, ktory jest napisany w kodzie natywnym i nie jest reprezentowany zadnym obiektem
// Javy - stad getClassLoader() zwraca null zamiast konkretnej instancji ClassLoader.

try {
    Class.forName("com.example.NieIstnieje");
} catch (ClassNotFoundException e) {
    System.out.println("Nie znaleziono klasy: " + e.getMessage());
}

// Bootstrap Class Loader to najwyzszy w hierarchii, wbudowany w sama JVM class loader,
// napisany w kodzie NATYWNYM (np. C++ w implementacji HotSpot), a nie w Javie. Laduje
// rdzen biblioteki standardowej - pakiety java.lang.*, java.util.* i inne fundamentalne
// klasy JDK. Poniewaz nie jest zaimplementowany jako zwykla klasa Javy dziedziczaca po
// java.lang.ClassLoader, nie ma zadnego obiektu Javy, ktory mogliby go reprezentowac -
// dlatego getClassLoader() dla klas ladowanych przez niego zwraca null.

static class Demo {
    static { System.out.println("Zainicjalizowano!"); }
}

System.out.println("Przed new Demo()");
Demo d = new Demo();
System.out.println("Po new Demo()");

System.out.println("1. Bootstrap - natywny, laduje rdzen JDK (java.lang.*, java.util.*)");
System.out.println("2. Platform - laduje moduly platformowe spoza rdzenia (XML, kryptografia)");
System.out.println("3. Application - laduje klasy z classpath/module path Twojej aplikacji");

ClassLoader cl1 = _Exercises_Lesson03_ClassLoadingMechanics.class.getClassLoader();
ClassLoader cl2 = _Exercises_Lesson03_ClassLoadingMechanics.class.getClassLoader();
System.out.println(cl1 == cl2); // true

System.out.println(java.util.ArrayList.class.getClassLoader());
System.out.println(String.class.getClassLoader());
System.out.println(java.util.ArrayList.class.getClassLoader() == String.class.getClassLoader()); // true, oba null

static class Lazy2 {
    static { System.out.println("Lazy2 zainicjalizowana"); }
    static void hello() { System.out.println("hello z Lazy2"); }
}

Class<?> loaded = Class.forName(Lazy2.class.getName(), false, Lazy2.class.getClassLoader());
System.out.println("Zaladowana, ale bez komunikatu powyzej z bloku statycznego");
Lazy2.hello(); // TUTAJ dopiero pojawia sie komunikat inicjalizacji

static class Eager { static { System.out.println("Eager zainicjalizowana OD RAZU"); } }
static class Lazy3 { static { System.out.println("Lazy3 zainicjalizowana PO OPOZNIENIU"); } }

Class.forName(Eager.class.getName()); // komunikat pojawia sie natychmiast
Class.forName(Lazy3.class.getName(), false, Lazy3.class.getClassLoader()); // brak komunikatu jeszcze

static void printChain(Class<?> clazz) {
    ClassLoader loader = clazz.getClassLoader();
    int i = 1;
    while (loader != null) {
        System.out.println(i++ + ". " + loader.getClass().getName());
        loader = loader.getParent();
    }
    System.out.println(i + ". null (Bootstrap)");
}
printChain(_Exercises_Lesson03_ClassLoadingMechanics.class);

static class WithCounter {
    static { System.out.println("WithCounter zainicjalizowana"); }
    static int counter = 10;
}

System.out.println("Zamierzam odczytac counter...");
System.out.println(WithCounter.counter); // TU widac komunikat z bloku statycznego

static class WithConstant {
    static { System.out.println("WithConstant zainicjalizowana - NIE POWINNO SIE POJAWIC"); }
    static final int VALUE = 42;
}

System.out.println(WithConstant.VALUE); // 42, ALE bez komunikatu inicjalizacji powyzej
// Kompilator 'wklejil' wartosc 42 BEZPOSREDNIO w miejsce uzycia (compile-time constant
// folding) - odczyt VALUE w ogole NIE wymaga zaladowania/inicjalizacji klasy WithConstant.

// Verification to podfaza Linking, w ktorej JVM SPRAWDZA, czy zaladowany bajtkod jest
// poprawny i bezpieczny - dziala NIEZALEZNIE od tego, czy bajtkod pochodzi z zaufanego
// kompilatora javac, czy zostal wygenerowany/zmodyfikowany recznie (np. przez narzedzie
// bytecode engineering jak ASM).
// Przyklad bledu wykrywanego przez weryfikator: instrukcja 'iadd' (dodawanie intow)
// wywolana, gdy na stosie operandow znajduja sie DWIE wartosci typu referencyjnego
// (obiekty) zamiast intow - taka niezgodnosc typow zostalaby wykryta i rzucony
// zostalby VerifyError, zanim klasa w ogole zostalaby zainicjalizowana.

// Przyklad: 'static int total = 100;'
// W FAZIE PREPARATION: JVM alokuje pamiec na pole 'total' i ustawia je na WARTOSC
// DOMYSLNA dla typu int, czyli 0 - jeszcze BEZ znajomosci wartosci 100 z kodu.
// W FAZIE INITIALIZATION (pozniej, przy pierwszym realnym uzyciu klasy): JVM WYKONUJE
// przypisanie 'total = 100;' jako czesc bloku inicjalizujacego klasy - dopiero TERAZ pole
// dostaje wartosc 100 podana w kodzie zrodlowym. Miedzy tymi fazami (teoretycznie) pole
// przez chwile ma wartosc 0, choc w praktyce ten stan posredni nie jest widoczny z
// zewnatrz przy normalnym, jednowatkowym uzyciu.

Class<?>[] classes = { String.class, java.util.ArrayList.class, java.time.LocalDate.class, _Exercises_Lesson03_ClassLoadingMechanics.class };
for (Class<?> c : classes) {
    System.out.println(c.getName() + " -> " + c.getClassLoader());
}
System.out.println("String i ArrayList maja wspolny loader: " + (String.class.getClassLoader() == java.util.ArrayList.class.getClassLoader()));

static class MultiBlock {
    static { System.out.println("Pierwszy blok statyczny"); }
    static int computed = compute();
    static { System.out.println("Drugi blok statyczny"); }
    static int compute() { System.out.println("compute() wywolane"); return 1; }
}

MultiBlock.computed; // wymusza inicjalizacje - kolejnosc: pierwszy blok, compute(), drugi blok

static class ViaLoadClass { static { System.out.println("ViaLoadClass zainicjalizowana"); } }

ClassLoader cl = ViaLoadClass.class.getClassLoader();
cl.loadClass(ViaLoadClass.class.getName()); // laduje, BEZ komunikatu
System.out.println("Po loadClass - brak komunikatu powyzej");

// Dla porownania: Class.forName("...") na innej, podobnej klasie wypisalby komunikat
// NATYCHMIAST, bo jednoargumentowy forName() zawsze inicjalizuje.

static String delegateParentFirst(String className, java.util.List<String> loaderOrder, java.util.Map<String, java.util.List<String>> knownClasses, int index) {
    if (index < loaderOrder.size() - 1) {
        String result = delegateParentFirst(className, loaderOrder, knownClasses, index + 1);
        if (result != null) return result;
    }
    String loader = loaderOrder.get(index);
    if (knownClasses.getOrDefault(loader, java.util.List.of()).contains(className)) {
        return loader;
    }
    return null;
}

static class Expensive {
    static { long sum = 0; for (int i = 0; i < 10_000_000; i++) sum += i; }
}

long t1 = System.nanoTime();
Class<?> loaded = Class.forName(Expensive.class.getName(), false, Expensive.class.getClassLoader());
long loadTime = System.nanoTime() - t1;

long t2 = System.nanoTime();
loaded.getDeclaredConstructor().newInstance(); // wymusza inicjalizacje
long initTime = System.nanoTime() - t2;

System.out.println("Ladowanie: " + loadTime + " ns, inicjalizacja: " + initTime + " ns");

static class Logger2 {
    static { System.out.println(System.nanoTime() + ": blok statyczny"); }
    Logger2() { System.out.println(System.nanoTime() + ": konstruktor"); }
    void method() { System.out.println(System.nanoTime() + ": metoda instancyjna"); }
}

Logger2 a = new Logger2(); a.method();
Logger2 b = new Logger2(); b.method();
// Blok statyczny pojawi sie TYLKO RAZ w calym dzienniku, konstruktor DWA razy.

static class Outer {
    static { System.out.println("Outer zainicjalizowana - NIE POWINNO SIE POJAWIC"); }
    static class Inner {
        static { System.out.println("Inner zainicjalizowana"); }
    }
}

new Outer.Inner(); // TYLKO 'Inner zainicjalizowana' powinno sie pojawic
// Obserwacja: klasa zagniezdzona statyczna jest DLA JVM zupelnie NIEZALEZNA klasa
// (kompiluje sie do 'Outer$Inner.class') - jej inicjalizacja NIE wymusza inicjalizacji
// klasy zewnetrznej Outer.

interface HasX {
    int X = compute();
    static int compute() { System.out.println("HasX.compute() wywolane"); return 99; }
}
static class Impl implements HasX { }

new Impl(); // Utworzenie instancji Impl NIE wymusza inicjalizacji HasX
System.out.println("Po new Impl() - brak komunikatu z compute() powyzej");
System.out.println(HasX.X); // DOPIERO odwolanie do X wymusza inicjalizacje interfejsu
// Obserwacja: implementowanie interfejsu przez klase NIE wymusza jego inicjalizacji -
// dzieje sie to dopiero przy faktycznym odwolaniu do pola statycznego interfejsu.

static class Tracker {
    static java.util.List<String> log = new java.util.ArrayList<>();
}
static class A { static { Tracker.log.add("A zainicjalizowana"); } }
static class B { static { Tracker.log.add("B zainicjalizowana"); } }

new B(); new A();
System.out.println(Tracker.log); // [B zainicjalizowana, A zainicjalizowana]

// -noverify/-Xverify:none (opcja historyczna, usunieta w nowszych JVM) pozwalala CALKOWICIE
// POMINAC faze Verification przy ladowaniu klas - motywacja byla wydajnosciowa (pominiecie
// weryfikacji bajtkodu przyspiesza start aplikacji, szczegolnie z DUZA liczba klas).
// Uzycie tej opcji bylo RYZYKOWNE, bo Verification jest kluczowa warstwa BEZPIECZENSTWA -
// gwarantuje, ze bajtkod (nawet wygenerowany/zmodyfikowany poza normalnym kompilatorem)
// nie zrobi niczego niebezpiecznego (np. dostepu poza granicami tablicy, mieszania typow
// na stosie operandow). Wylaczenie weryfikacji otwiera droge do UB (undefined behavior)
// lub potencjalnych lukach bezpieczenstwa przy zaladowaniu zlosliwego/uszkodzonego bajtkodu.

try {
    Class.forName("nie.istnieje.Klasa");
} catch (ClassNotFoundException e) {
    System.out.println("Zlapano: " + e.getMessage());
}
// ClassNotFoundException wystepuje, gdy JAWNIE probujemy zaladowac klase po nazwie
// (Class.forName/loadClass), a klasa NIE ISTNIEJE na classpath - to CHECKED wyjatek,
// zglaszany podczas proby fazy LOADING.
// NoClassDefFoundError wystepuje, gdy klasa BYLA dostepna PODCZAS KOMPILACJI (kod
// odwoluje sie do niej wprost, bez refleksji), ale zniknela z classpath W CZASIE
// URUCHOMIENIA (np. brakujacy JAR w runtime) - to Error (nie Exception), rzucany przy
// probie UZYCIA (INITIALIZATION/normalne wywolanie), nie przy jawnym Class.forName.

static class FullLifecycle {
    static { System.out.println("[2] INICJALIZACJA: blok statyczny wykonany"); }
    static int counter = 0;
    FullLifecycle() { System.out.println("[3] INSTANCJA: konstruktor wywolany"); }
    void doWork() { System.out.println("[4] METODA: doWork() wywolana"); }
}

Class<?> loaded = Class.forName(FullLifecycle.class.getName(), false, FullLifecycle.class.getClassLoader());
System.out.println("[1] LADOWANIE: klasa zaladowana bez inicjalizacji");
FullLifecycle f = (FullLifecycle) loaded.getDeclaredConstructor().newInstance();
f.doWork();

printChain(Object.class);
printChain(java.util.regex.Pattern.class);
printChain(_Exercises_Lesson03_ClassLoadingMechanics.class);
// Object i Pattern maja loader == null (Bootstrap, rdzen JDK). Wlasna klasa kursu ma
// niepusty loader (Application/System ClassLoader) - roznica pokazuje, ze klasy JDK
// pochodza z samego srodowiska uruchomieniowego, a klasy kursu z naszego classpath.
